import React, { forwardRef, useRef, useLayoutEffect } from 'react';
import { X } from '@hexa-ui/icons';

import { DateRange, Matcher } from 'react-day-picker';
import { format } from 'date-fns';
import { Button } from '../../../button';
import { Calendar, CalendarRef } from '../../../calendar';
import { Card } from '../../../card';
import { Divider } from '../../../divider';
import { IconButton } from '../../../icon-button';
import { Input } from '../../../input';
import { TextLink } from '../../../text-link';
import { Paragraph } from '../../../typography';
import { Content, Row } from './DatePickerBase.styles';
import { DatePickerBaseProps } from './DatePickerBase.types';
import { getTranslateLabel, getTranslationsDate } from '../../../../utils';

export const DatePickerBase = forwardRef(
  (
    {
      onReset,
      onSave,
      onChange,
      onClose,
      mode = 'single',
      numberOfMonths = 1,
      type,
      sideContent,
      callToActionSection = false,
      value,
      defaultValue,
      customLocale,
      ...rest
    }: DatePickerBaseProps,
    forwardedRef: React.ForwardedRef<HTMLDivElement>
  ): JSX.Element => {
    const calendarRef = useRef<CalendarRef>(null);

    const locale = getTranslationsDate(customLocale);
    const formatDate = getTranslateLabel('formatDate', customLocale);
    const toLabel = getTranslateLabel('to', customLocale);

    useLayoutEffect(() => {
      if (!value) return;
      if (mode === 'range') {
        calendarRef.current?.changeSelection({ from: value[0], to: value[1] });
      } else {
        calendarRef.current?.changeSelection(value);
      }
    }, [value, mode]);

    const handleSelect = (selection: Matcher | Matcher[] | undefined) => {
      if (selection === undefined) {
        onChange();
      } else if (selection instanceof Date) {
        onChange([selection] as Date[]);
      } else {
        const range = selection as DateRange;
        onChange([range.from, range.to] as Date[]);
      }
    };

    const handleReset = () => {
      onReset?.();

      if (mode === 'range') {
        if (!defaultValue?.[0] && !defaultValue?.[1]) {
          calendarRef.current?.clearSelection();
          return;
        }

        calendarRef.current?.changeSelection({ from: defaultValue[0], to: defaultValue[1] });
      } else {
        if (!defaultValue) {
          calendarRef.current?.clearSelection();
          return;
        }
        calendarRef.current?.changeSelection(defaultValue);
      }
    };

    return (
      <Card border="medium" elevated="medium" ref={forwardedRef} data-testid="date-picker-calendar">
        <Row css={{ alignItems: 'stretch' }}>
          {type === 'panel-left' && (
            <>
              {sideContent}
              <Divider orientation="vertical" css={{ height: 'auto !important' }} />
            </>
          )}

          <Content
            css={{
              padding: ['panel-right', 'panel-left'].includes(type as string)
                ? '$6 $8 $6 $8'
                : '$6 $8 $8 $8',
            }}
          >
            {mode === 'single' && (
              <Row>
                <Input
                  type="text"
                  width="19.6875rem"
                  readOnly
                  value={format(value?.[0] ?? new Date(), formatDate, { locale })}
                />
                {numberOfMonths === 2 && (
                  <IconButton
                    icon={X}
                    variant="tertiary"
                    size="small"
                    onClick={onClose}
                    data-testid="icon-button-close-x"
                  />
                )}
              </Row>
            )}
            {mode === 'range' && (
              <Row css={{ gap: '$4', justifyContent: 'flex-end' }}>
                <Input
                  type="text"
                  width="11.25rem"
                  readOnly
                  value={format(value?.[0] ?? new Date(), formatDate, { locale })}
                />
                <Paragraph
                  css={{
                    lineHeight: '$5',
                    fontWeight: '$semibold',
                    fontSize: '$2',
                    textAlign: 'center',
                  }}
                >
                  {toLabel}
                </Paragraph>
                <Input
                  type="text"
                  width="11.25rem"
                  readOnly
                  value={format(value?.[1] || value?.[0] || new Date(), formatDate, { locale })}
                />
              </Row>
            )}
            <div style={{ display: 'grid', placeItems: 'center' }}>
              <Calendar
                onChange={handleSelect}
                mode={mode}
                numberOfMonths={numberOfMonths}
                ref={calendarRef}
                defaultMonth={value?.[0]}
                customLocale={customLocale}
                {...rest}
              />
            </div>
          </Content>

          {type === 'panel-right' && (
            <>
              <Divider orientation="vertical" css={{ height: 'auto !important' }} />
              {sideContent}
            </>
          )}
        </Row>

        {['panel-right', 'panel-left'].includes(type as string) && <Divider />}

        {callToActionSection && (
          <Row
            css={{
              padding: ['panel-right', 'panel-left'].includes(type as string)
                ? '$4 $8 $4 $8'
                : '0 $8 $8 $8',
            }}
          >
            <TextLink
              hasUnderline={false}
              onClick={handleReset}
              data-testid="date-picker-reset-button"
            >
              Reset
            </TextLink>
            <Button
              type="button"
              size="large"
              onClick={onSave}
              data-testid="date-picker-save-button"
            >
              Save
            </Button>
          </Row>
        )}
      </Card>
    );
  }
);
